const CONTI = ['banca', 'contante', 'paypal', 'satispay', 'revolut'];
const CONTO_DEFAULT = 'banca';
const RE_DOMANDA = /^\s*(quant|quand|dove|cosa|che\s|mostra|elenca|cerca|trova|riepilog)/i;



function normalizza(s) {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

const msg = $input.first().json.message;
const testo = msg.text || msg.caption || '';

const iniziaConNumero = /^\s*[+-]?\s*\d/.test(testo);
const eDomanda = !iniziaConNumero &&
                 (RE_DOMANDA.test(testo) || /\?\s*$/.test(testo.trim()));

if (eDomanda) {
  return [{ json: {
    eDomanda,
    chat_id: msg.chat.id,
    message_id: msg.message_id,
    testo,
  }}];
}

// Se c'e' un numero con i decimali quello e' quasi sempre l'importo
// ("cena 4 amici 30,50"); altrimenti prendo il primo numero.
const m = testo.match(/([+-]?)\s*(\d+[.,]\d{1,2})\b/) ||
          testo.match(/([+-]?)\s*(\d+)\b/);

if (!m) {
  return [{ json: {
    text: 'Non ho capito. Prova tipo: 12,50 pizza  oppure  +2400 stipendio oppure una domanda sulle tue spese.',
    parse_mode: 'HTML',
    disable_web_page_preview: true,
}}];
}

const importo = parseFloat(m[2].replace(',', '.'));
const tipo = m[1] === '+' ? 'entrata' : 'spesa';

let resto = testo.replace(m[0], ' ').trim();
let conto = CONTO_DEFAULT;
for (const c of CONTI) {
  const re = new RegExp('\\b' + c + '\\b', 'i');
  if (re.test(resto)) { conto = c; resto = resto.replace(re, '').trim(); }
}

// "@" marca l'esercente: "20 pizza @da michele" -> pizza / da michele.
// Senza chiocciola resta tutto descrizione, che e' il caso normale.
let esercente = '';
let descrizione = resto;
const at = resto.match(/@\s*(.+)$/);
if (at) {
  esercente = normalizza(at[1]);
  descrizione = resto.slice(0, at.index).trim();
}


return [{ json: {
  modo: 'movimento',
  valido: true,
  chat_id: msg.chat.id,
  message_id: msg.message_id,
  testo_grezzo: testo,
  importo,
  tipo,
  conto,
  esercente,
  descrizione: normalizza(descrizione),
}}];

const tx = $('Decidi categoria').first().json;

// Hash a 64 bit (FNV-1a). Non e' crittografia: serve solo come chiave
// di identita' per la deduplica, e il Code node di n8n non espone crypto.
function hash64(str) {
  let h = 0xcbf29ce484222325n;
  const p = 0x100000001b3n;
  for (let i = 0; i < str.length; i++) {
    h ^= BigInt(str.charCodeAt(i));
    h = (h * p) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, '0');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

let categoria = tx.categoria;
let confidenza = tx.confidenza ?? 0.2;

if (!tx.categoria) {
  try {
    const risposta = $('Gemini').first().json;
    const testo = risposta.candidates[0].content.parts[0].text
      .replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(testo);
    if (tx.categorie_disponibili.includes(parsed.categoria)) {
      categoria = parsed.categoria;
      confidenza = Number(parsed.confidenza) || 0.5;
    }
  } catch (e) {
    // Gemini muto o risposta illeggibile: ripiego e chiedo conferma.
  }
  if (!categoria) { categoria = tx.categorie_disponibili[0]; confidenza = 0.2; }
}

const oggi = new Date().toISOString().slice(0, 10);
const daVerificare = confidenza < 0.75;

// Cosa mostrare nella risposta: il posto se lo conosci, altrimenti cosa hai preso.
const etichetta = tx.esercente || tx.descrizione;

// Il message_id di Telegram rende l'hash unico per messaggio: se Telegram
// ritrasmette lo stesso update, l'hash coincide e il doppione e' visibile.
const hash = hash64([oggi, tx.importo.toFixed(2), etichetta,
                     tx.conto, tx.message_id].join('|'));

const id = uuid();
const segno = tx.tipo === 'entrata' ? '+' : '−';

const risposta_testo = segno + ' ' +
  tx.importo.toFixed(2).replace('.', ',') + ' €  ' + categoria +
  (etichetta ? '<br>' + etichetta : '') + '<br>' + tx.conto +
  (daVerificare ? '<br><br>Categoria incerta, confermi?' : '');

// Bottoni solo se la confidenza e' bassa.
// Nella callback viaggiano l'hash (chiave di riga) e il NOME della categoria:
// cosi' al ritorno non serve ricostruire nessuna lista. Telegram limita
// callback_data a 64 byte, da cui il filtro sui nomi lunghi.
let tastiera = null;
if (daVerificare) {
  const cats = tx.categorie_disponibili.filter(c => c.length <= 40);
  const righe = [];
  for (let i = 0; i < cats.length; i += 2) {
    righe.push(cats.slice(i, i + 2).map(c => ({
      text: c,
      callback_data: 'c|' + hash + '|' + c,
    })));
  }
  righe.push([{ text: 'Va bene cosi', callback_data: 'ok|' + hash + '|' + categoria }]);
  tastiera = { inline_keyboard: righe };
}

// Il payload per Telegram si costruisce qui, dove i dati ci sono gia'.
// reply_markup viene aggiunto solo se serve: passarlo a null fa storcere
// il naso all'API.
const payload = { chat_id: tx.chat_id, text: risposta_testo };
if (tastiera) payload.reply_markup = tastiera;

// Gia' serializzato: nel nodo HTTP basta referenziarlo, niente
// JSON.stringify dentro l'espressione.
const payload_json = JSON.stringify(payload);

return [{ json: {
  riga: {
    id,
    data_evento: oggi,
    data_inserimento: new Date().toISOString(),
    fonte: 'telegram',
    tipo: tx.tipo,
    importo: tx.importo.toFixed(2),
    valuta: 'EUR',
    conto: tx.conto,
    esercente: tx.esercente,
    categoria,
    sottocategoria: '',
    note: tx.descrizione,
    testo_grezzo: tx.testo_grezzo,
    hash_dedup: hash,
    confidenza: confidenza.toFixed(2),
    stato: daVerificare ? 'da_verificare' : 'confermata',
  },
  payload,
  payload_json,
}}];

const cb = $input.first().json.callback_query;

// callback_data = "<azione>|<hash>|<categoria>"
// La categoria viaggia gia' risolta: niente indici da reinterpretare.
const parti = String(cb.data).split('|');

return [{ json: {
  azione: parti[0],
  chiave: parti[1],
  categoria: parti.slice(2).join('|'),
  chat_id: cb.message.chat.id,
  message_id: cb.message.message_id,
  callback_id: cb.id,
}}];

function normalizza(s) {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

const tx = $('Estrai transazione').first().json;

const regole = $('Leggi Regole').all()
  .map(i => i.json)
  .filter(r => normalizza(String(r.pattern || '')).length >= 2);

const categorie = $('Leggi Categorie').all()
  .map(i => i.json)
  .filter(c => c.categoria && String(c.tipo).toLowerCase() === tx.tipo)
  .map(c => String(c.categoria));

// 1) Regole locali: gratis e istantanee.
// Il match avviene su esercente + descrizione insieme, cosi' funziona sia
// con "@coop" sia con "spesa settimanale".
const testoMatch = normalizza((tx.esercente || '') + ' ' + (tx.descrizione || ''));
const regola = regole.find(r => testoMatch &&
  testoMatch.includes(normalizza(r.pattern)));

if (regola) {
  return [{ json: {
    ...tx,
    categoria: String(regola.categoria),
    confidenza: 1,
    serve_ai: false,
    categorie_disponibili: categorie,
  }}];
}

// 2) Niente regola: prepariamo il prompt per Gemini.
const prompt = 'Classifica questa transazione in UNA delle categorie elencate.\n\n' +
  'Categorie ammesse:\n' + categorie.join('\n') + '\n\n' +
  'Descrizione: "' + [tx.esercente, tx.descrizione].filter(Boolean).join(' ') +
  '"\n\n' +
  'Rispondi solo con JSON: {"categoria": "<una delle categorie>", "confidenza": <0.0-1.0>}\n' +
  'La confidenza sia bassa se la descrizione e ambigua.';

const body = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json' },
};
return [{ json: {
  ...tx,
  categoria: '',
  prompt,
  serve_ai: true,
  body_json: JSON.stringify(body),
  categorie_disponibili: categorie,
}}];

const c = $('Leggi conferma').first().json;
// callback_data = "att|<hash>|reg" oppure "att|<hash>|ann"
return [{ json: {
  hash: c.chiave,
  stato: c.categoria === 'reg' ? 'confermata' : 'eliminata',
  testo: c.categoria === 'reg' ? 'Registrata' : 'Annullata',
  callback_id: c.callback_id,
}}];

const prep = $('Prepara domanda').first().json;
const risposta = $('Gemini domanda').first().json;

const parts = risposta?.candidates?.[0]?.content?.parts || [];
const grezzo = parts.map(p => p.text).filter(Boolean).join('')
  .replace(/```json|```/g, '').trim();

let f = null;
try { f = JSON.parse(grezzo); } catch { f = null; }

const fallito = (msg) => [{ json: { chat_id: prep.chat_id, errore: msg } }];

if (!f) return fallito('Non sono riuscito a interpretare la domanda. Riprova.');
if (f.capita === false) {
  return fallito('Rispondo solo a domande su spese e movimenti. Prova con ' +
                 '"quanto ho speso in ristoranti a luglio".');
}

// --- validazione di ogni campo ---
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const numOrNull = (v) =>
  (v === null || v === undefined || v === '') ? null
  : (Number.isFinite(Number(v)) ? Number(v) : null);

// La categoria deve esistere davvero: il confronto è insensibile alle
// maiuscole e riconduce al nome esatto del foglio.
const cat = prep.categorie.find(c =>
  c.toLowerCase() === String(f.categoria || '').toLowerCase()) || null;

let da = ISO.test(String(f.da)) ? String(f.da) : null;
let a  = ISO.test(String(f.a))  ? String(f.a)  : null;
if (da && a && da > a) { const t = da; da = a; a = t; }   // intervallo invertito

const filtro = {
  azione: 'cerca',
  q: f.q ? String(f.q).slice(0, 60) : null,
  da, a,
  categoria: cat,
  tipo: ['spesa', 'entrata'].includes(f.tipo) ? f.tipo : null,
  min: numOrNull(f.min),
  max: numOrNull(f.max),
  limite: 200,
};

// Un filtro completamente vuoto restituirebbe tutto lo storico: quasi sempre
// significa che la domanda non è stata capita.
const vuoto = !filtro.q && !filtro.da && !filtro.a && !filtro.categoria &&
              !filtro.tipo && filtro.min === null && filtro.max === null;
if (vuoto) return fallito('Non ho capito su cosa cercare. Prova a indicare un ' +
                          'periodo, una categoria o un nome.');

const agg = ['totale', 'elenco', 'per_categoria'].includes(f.aggregazione)
  ? f.aggregazione : 'totale';

return [{ json: {
  chat_id: prep.chat_id,
  aggregazione: agg,
  filtro,
  filtro_json: JSON.stringify(filtro),
}}];

const q = $('Estrai transazione').first().json;

const categorie = $('Leggi Categorie1').all().map(i => i.json)
  .filter(c => c.categoria).map(c => String(c.categoria));

// Il modello deve sapere che giorno è, altrimenti "a luglio" non ha senso.
const oggi = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });

const prompt =
  'Traduci la domanda in un filtro di ricerca. Oggi è ' + oggi + '.\n\n' +
  'Categorie esistenti:\n' + categorie.join('\n') + '\n\n' +
  'Domanda: "' + q.testo + '"\n\n' +
  'Rispondi solo con JSON:\n' +
  '{"capita": true|false, "q": "<parole chiave>"|null,\n' +
  ' "da": "YYYY-MM-DD"|null, "a": "YYYY-MM-DD"|null,\n' +
  ' "categoria": "<una delle categorie>"|null,\n' +
  ' "tipo": "spesa"|"entrata"|null,\n' +
  ' "min": <numero>|null, "max": <numero>|null,\n' +
  ' "aggregazione": "totale"|"elenco"|"per_categoria"}\n\n' +
  'Regole:\n' +
  '- Interpreta il tempo rispetto a oggi. "luglio" senza anno è il luglio più ' +
  'recente già iniziato. "questo mese" è il mese di oggi. "ultimi tre mesi" ' +
  'parte da tre mesi fa e arriva a oggi. "l anno scorso" è l anno solare ' +
  'precedente per intero.\n' +
  '- Se non c è alcun riferimento temporale, lascia da e a a null: la ricerca ' +
  'coprirà tutto lo storico.\n' +
  '- aggregazione: "quanto ho speso" -> totale. "cosa", "quali", "mostrami", ' +
  '"elenca" -> elenco. "come ho speso", "in cosa", "per categoria" -> ' +
  'per_categoria.\n' +
  '- categoria SOLO se coincide con una dell elenco. Altrimenti null, e le ' +
  'parole rilevanti finiscono in q.\n' +
  '- q contiene il nome di un esercente o di un luogo, mai parole generiche ' +
  'come "speso", "soldi", "spese". Se non ce n è, null.\n' +
  '- capita false se la domanda non riguarda movimenti, spese o entrate.';

return [{ json: {
  chat_id: q.chat_id,
  testo: q.testo,
  categorie,
  body_json: JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { responseMimeType: 'application/json' },
  }),
}}];

const f = $('Leggi filtro').first().json;
const r = $('Chiama ricerca').first().json || {};

const eur = (n) => (Math.round(Number(n) * 100) / 100).toFixed(2)
  .replace('.', ',') + ' €';
const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const gg = (d) => String(d).slice(8) + '/' + String(d).slice(5, 7);

if (r.ok === false || r.error || !Number.isFinite(Number(r.conteggio))) {
  return [{ json: {
      text: 'La ricerca non è riuscita. Riprova fra poco.',
  }}];
}

let t;

if (!r.conteggio) {
  t = 'Nessun movimento trovato.';
} else if (f.aggregazione === 'elenco') {
  const righe = (r.movimenti || []).slice(0, 15).map(m =>
    gg(m.data) + '  ' + eur(m.importo) + '  ' + esc(m.etichetta || m.categoria));
  t = '<b>' + r.conteggio + ' movimenti · ' + eur(r.totale) + '</b><br><br>' +
      righe.join('<br>');
  if (r.conteggio > 15) t += '<br>…e altri ' + (r.conteggio - 15);
} else if (f.aggregazione === 'per_categoria') {
  const righe = (r.per_categoria || []).slice(0, 12).map(c =>
    esc(c.nome) + ': ' + eur(c.totale));
  t = '<b>' + eur(r.totale) + '</b> in ' + r.conteggio + ' movimenti<br><br>' +
      righe.join('<br>');
} else {
  t = '<b>' + eur(r.totale) + '</b>\n' + r.conteggio + ' movimenti';
}

// Cosa ha capito il modello, sempre in fondo. Senza questa riga un
// fraintendimento sul periodo produrrebbe un numero sbagliato dall'aria
// perfettamente credibile.
const pezzi = [];
if (f.filtro.da || f.filtro.a) {
  pezzi.push((f.filtro.da ? gg(f.filtro.da) + '/' + String(f.filtro.da).slice(0, 4) : 'inizio') +
             ' → ' +
             (f.filtro.a ? gg(f.filtro.a) + '/' + String(f.filtro.a).slice(0, 4) : 'oggi'));
} else {
  pezzi.push('tutto lo storico');
}
if (f.filtro.categoria) pezzi.push(esc(f.filtro.categoria));
if (f.filtro.q) pezzi.push('"' + esc(f.filtro.q) + '"');
if (f.filtro.tipo) pezzi.push(f.filtro.tipo);

t += '<br><br><i>' + pezzi.join(' · ') + '</i>';

return [{ json: {
    text: t.slice(0, 4000),
}}];

const e = $json;
return [{ json: {
text: e.errore ,
}}];
